import{_ as a,o as e,c as o,ag as d}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"义","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-义.md","filePath":"50-概念资料/dict-义.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-义.md"};function l(i,t,h,u,n,c){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="义" tabindex="-1">义 <a class="header-anchor" href="#义" aria-label="Permalink to &quot;义&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：正命 | 道家对应：道义</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;义&quot;就是<strong>该做的事就做，不该做的事不做</strong>。了空居士非常务实——不把&quot;义&quot;说得高不可攀，而是与&quot;利&quot;辩证统一：义和利在整体观下是一致的。对整体有利的就是义，对整体有害的就是不义。</p><p>关键操作：用<strong>道理和良心</strong>来判断。守住这两条，永远立于不败之地。了空居士不搞&quot;义利对立&quot;——&quot;该花一万我不会花九千，不该花的五元我都不愿意花&quot;——这就是义。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;我们总结的经验就是用道理和良心和人家对论。评价一件事情都是用道理和良心，只要守住这两条，永远立于不败之地。&quot; — 修行入世（20090112b）</p></blockquote><blockquote><p>&quot;该花一万我不会花九千，不该花的五元，我可能五元钱都不愿意花，我会看得很准的。&quot; — 答疑专辑2019_处世篇</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>义就是不要钱、不要利</td><td>义是以正当方式获取利益，自利利他</td></tr><tr><td>义是死板的道德教条</td><td>义是看具体情境的——武松打虎是义（除害），现代打虎不义</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>侧重</th></tr></thead><tbody><tr><td>儒家</td><td>义</td><td>道德上的&quot;应该&quot;，见义勇为</td></tr><tr><td>佛家</td><td>正命</td><td>正当的生计和行为</td></tr><tr><td>道家</td><td>道义</td><td>符合道的行事</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-正">dict-正</a> — 义和正的判断标准一致：整体利益</li><li><a href="/50-概念资料/dict-恕">dict-恕</a> — 义利冲突时，用恕来检验</li><li><a href="/50-概念资料/dict-处世">dict-处世</a> — 义是处世中做决策的准则</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/meta-整体观">meta-整体观</a> — 用整体观定义利——对整体有益的就是义</li><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 义不是极端——该花的要花，不该省的不省</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>遇到利益冲突时，用整体观判断：哪一方对整体更有利？守住道理和良心两条底线。该花的不省，不该花的不浪费。</p>',18)])])}const b=a(r,[["render",l]]);export{s as __pageData,b as default};
